/**
 * Each news article's banner, drawn at build by next/og: the shared banner art
 * with the article's own lockup on its center line.
 *
 * The art is brand/news/banner-base-on-{light,dark}.svg, generated by
 * `pnpm brand:banners`: the substrate and instrument chrome every banner
 * shares. The lockup is what makes the banner the article's own:
 *
 * - a reticle around the article's category glyph, as on the category banners
 *   this replaces;
 * - the article's subject, in the share card's headline face;
 * - a readout of the identifiers among its tags (ECIP, ECBP, EIP, BIP, SLIP)
 *   and its date.
 *
 * A banner sits directly above the article's title, category and date in the
 * markup, so it carries no headline. The banner is inverted against the page,
 * a dark banner on a light page and the reverse, and the caller picks the file
 * for the page it shows on: see the generator's docstring for why the image
 * cannot pick for itself.
 *
 * The art is drawn at 800x400 and the banner rendered at twice that, so every
 * geometry constant below is in the art's units and doubled on the way out.
 */
import { ImageResponse } from 'next/og'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import palettes from '@/brand/news/banner-palettes.json'
import { assertSupported, displayWidth, monoWidth, ogFonts } from '@/lib/og-fonts'
import type { Article, ArticleCategory } from '../data/articles'

export const BANNER_SIZE = { width: 1600, height: 800 }
export type BannerPage = 'light' | 'dark'

const SCALE = BANNER_SIZE.width / 800

/** The reticle's radius, and the halo's, from the category banners' lockup. */
const R = 46
const HALO = R + 62
/** From the reticle's edge to the subject. */
const GAP = 30
/** The circuit stops at x 200 and x 600, so the lockup keeps inside 400 units. */
const LOCKUP_MAX = 400
const TEXT_MAX = LOCKUP_MAX - 2 * R - GAP

/** The subject is set like a card headline: Inter Display Bold, tracked tight. */
const SUBJECT_SIZES = [32, 29, 26, 23, 20]
const SUBJECT_TRACKING = -0.02
const READOUT_SIZE = 10
const READOUT_TRACKING = 0.08

/**
 * Heroicons v2 24-outline glyphs, one per category, carried over from the
 * category banners. Ecosystem is a node graph rather than a globe: a generic
 * globe says nothing a blockchain reader needs, and the graph echoes the
 * circuit layer's via pads.
 */
const GLYPHS: Record<ArticleCategory, string> = {
  Updates:
    '<path d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99"/>',
  Security:
    '<path d="M9 12.75 11.25 15 15 9.75m-3-7.036A11.959 11.959 0 0 1 3.598 6 11.99 11.99 0 0 0 3 9.749c0 5.592 3.824 10.29 9 11.623 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.571-.598-3.751h-.152c-3.196 0-6.1-1.248-8.25-3.285Z"/>',
  Ecosystem:
    '<path d="M12 12 12 4M12 12 4.7 8.2M12 12l7.3-3.8M12 12l-5 7.4M12 12l5 7.4"/><circle cx="12" cy="3.2" r="1.9"/><circle cx="3.6" cy="7.6" r="1.9"/><circle cx="20.4" cy="7.6" r="1.9"/><circle cx="6.4" cy="20.1" r="1.9"/><circle cx="17.6" cy="20.1" r="1.9"/><circle cx="12" cy="12" r="2.4"/>',
  Community:
    '<path d="M15 19.128a9.38 9.38 0 0 0 2.625.372 9.337 9.337 0 0 0 4.121-.952 4.125 4.125 0 0 0-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 0 1 8.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0 1 11.964-3.07M12 6.375a3.375 3.375 0 1 1-6.75 0 3.375 3.375 0 0 1 6.75 0Zm8.25 2.25a2.625 2.625 0 1 1-5.25 0 2.625 2.625 0 0 1 5.25 0Z"/>',
  Development: '<path d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5"/>',
}

type Palette = (typeof palettes)['on-dark']

/** The reticle, its halo and the glyph, as one SVG centered on its own origin. */
function reticleSvg(category: ArticleCategory, p: Palette): string {
  const point = (r: number, deg: number) => {
    const a = (deg * Math.PI) / 180
    return `${(r * Math.cos(a)).toFixed(2)} ${(r * Math.sin(a)).toFixed(2)}`
  }
  const ticks = [
    [0, -1],
    [0, 1],
    [-1, 0],
    [1, 0],
  ]
    .map(
      ([dx, dy]) =>
        `<line x1="${dx * (R - 5)}" y1="${dy * (R - 5)}" x2="${dx * (R + 7)}" y2="${dy * (R + 7)}" stroke-opacity="${p.a_ret2}" stroke-width="1.3"/>`
    )
    .join('')
  // Quadrant arcs at 45 degrees, the part that makes it read as tracking.
  const arcs = [30, 120, 210, 300]
    .map((a0) => `<path d="M${point(R + 13, a0)} A${R + 13} ${R + 13} 0 0 1 ${point(R + 13, a0 + 30)}" stroke-opacity="${p.a_ret}" stroke-width="1.2"/>`)
    .join('')

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-HALO} ${-HALO} ${2 * HALO} ${2 * HALO}" width="${2 * HALO * SCALE}" height="${2 * HALO * SCALE}">`,
    `<defs><radialGradient id="halo"><stop offset="0%" stop-color="${p.ink}" stop-opacity="0.09"/><stop offset="100%" stop-color="${p.ink}" stop-opacity="0"/></radialGradient></defs>`,
    `<circle r="${HALO}" fill="url(#halo)"/>`,
    `<g fill="none" stroke="${p.ink}">`,
    `<circle r="${R}" stroke-opacity="${p.a_ret}" stroke-width="1.1"/>`,
    `<circle r="${R - 9}" stroke-opacity="${p.a_ret}" stroke-width="0.75" stroke-dasharray="3 7"/>`,
    ticks,
    arcs,
    '</g>',
    `<g transform="translate(-24 -24) scale(2)" fill="none" stroke="${p.ink}" stroke-opacity="${p.a_glyph}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">`,
    GLYPHS[category],
    '</g>',
    '</svg>',
  ].join('')
}

const IDENTIFIER = /^(ECIP|ECBP|EIP|BIP|SLIP)-\d+$/i

/** The identifiers among the article's tags, then its date, as many as fit. */
export function bannerReadout(article: Pick<Article, 'tags' | 'date'>): string {
  const ids = (article.tags ?? []).filter((tag) => IDENTIFIER.test(tag)).map((tag) => tag.toUpperCase())
  for (let keep = ids.length; keep >= 0; keep--) {
    const readout = [...ids.slice(0, keep), article.date].join('  ·  ')
    if (monoWidth(readout, READOUT_SIZE, READOUT_TRACKING) <= TEXT_MAX) return readout
  }
  return article.date
}

function subjectSize(subject: string): number {
  const size = SUBJECT_SIZES.find((s) => displayWidth(subject, s, SUBJECT_TRACKING) <= TEXT_MAX)
  if (!size) {
    throw new Error(
      `news banner: the subject "${subject}" is wider than ${TEXT_MAX} units at ${SUBJECT_SIZES.at(-1)}px. Shorten it in app/news/data/articles.ts.`
    )
  }
  return size
}

const art = new Map<BannerPage, string>()

async function artDataUri(page: BannerPage): Promise<string> {
  const hit = art.get(page)
  if (hit) return hit
  const svg = await readFile(join(process.cwd(), 'brand/news', `banner-base-on-${page}.svg`))
  const uri = `data:image/svg+xml;base64,${svg.toString('base64')}`
  art.set(page, uri)
  return uri
}

export async function renderBanner(
  article: Pick<Article, 'category' | 'subject' | 'tags' | 'date'>,
  page: BannerPage
): Promise<ImageResponse> {
  const subject = article.subject ?? article.category
  const readout = bannerReadout(article)
  assertSupported('news banner', 'subject', subject)
  assertSupported('news banner', 'readout', readout)

  const p = palettes[`on-${page}`]
  const size = subjectSize(subject)
  const reticle = `data:image/svg+xml;base64,${Buffer.from(reticleSvg(article.category, p)).toString('base64')}`
  const [fonts, background] = await Promise.all([ogFonts(), artDataUri(page)])
  const s = (units: number) => units * SCALE

  return new ImageResponse(
    (
      <div style={{ display: 'flex', position: 'relative', width: '100%', height: '100%' }}>
        {/* eslint-disable-next-line @next/next/no-img-element -- next/og draws this, no browser loads it */}
        <img src={background} width={BANNER_SIZE.width} height={BANNER_SIZE.height} alt="" style={{ position: 'absolute', top: 0, left: 0 }} />

        {/* The lockup, centered as one unit: the halo overhangs the reticle, so its margins pull the layout in to the reticle's edge. */}
        <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          {/* eslint-disable-next-line @next/next/no-img-element -- next/og draws this, no browser loads it */}
          <img
            src={reticle}
            width={s(2 * HALO)}
            height={s(2 * HALO)}
            alt=""
            style={{ marginLeft: -s(HALO - R), marginRight: -s(HALO - R - GAP) }}
          />
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <div
              style={{
                display: 'flex',
                whiteSpace: 'nowrap',
                fontFamily: 'Inter Display',
                fontWeight: 700,
                fontSize: s(size),
                lineHeight: 1.1,
                letterSpacing: s(SUBJECT_TRACKING * size),
                color: p.tx,
              }}
            >
              {subject}
            </div>
            <div
              style={{
                display: 'flex',
                whiteSpace: 'nowrap',
                marginTop: s(6),
                fontFamily: 'JetBrains Mono',
                fontWeight: 500,
                fontSize: s(READOUT_SIZE),
                letterSpacing: s(READOUT_TRACKING * READOUT_SIZE),
                color: p.ink,
              }}
            >
              {readout}
            </div>
          </div>
        </div>
      </div>
    ),
    { ...BANNER_SIZE, fonts }
  )
}
